import ast,sys
src=open('scripts/db.py').read(); t=ast.parse(src)
# every use of name 'subprocess' and enclosing function, whether function has local import
for fn in ast.walk(t):
    if isinstance(fn,(ast.FunctionDef,ast.Module)):
        pass
uses=[n for n in ast.walk(t) if isinstance(n,ast.Name) and n.id=='subprocess']
imps=[n for n in ast.walk(t) if isinstance(n,(ast.Import,ast.ImportFrom)) and any((a.asname or a.name).split('.')[0]=='subprocess' for a in n.names)]
print('uses',[u.lineno for u in uses]); print('imports',[(i.lineno,i.col_offset) for i in imps])
# string forms
import re
print('string mentions',[i+1 for i,l in enumerate(src.splitlines()) if 'subprocess' in l])
# top-level names referenced but never bound anywhere (cheap undefined check)
import builtins
bound=set(dir(builtins))
for n in ast.walk(t):
    if isinstance(n,(ast.FunctionDef,ast.ClassDef,ast.AsyncFunctionDef)): bound.add(n.name)
    elif isinstance(n,ast.Name) and isinstance(n.ctx,(ast.Store,ast.Del)): bound.add(n.id)
    elif isinstance(n,(ast.Import,ast.ImportFrom)):
        for a in n.names: bound.add((a.asname or a.name).split('.')[0])
    elif isinstance(n,ast.arg): bound.add(n.arg)
    elif isinstance(n,ast.ExceptHandler) and n.name: bound.add(n.name)
print('unbound',sorted({n.id for n in ast.walk(t) if isinstance(n,ast.Name) and isinstance(n.ctx,ast.Load) and n.id not in bound}))
